public static int findNthLeapYear(int Y, int N) {
    // Helper to determine if a year is a leap year
    java.util.function.IntPredicate isLeap = year -> {
        if (year % 400 == 0) return true;
        if (year % 100 == 0) return false;
        return year % 4 == 0;
    };

    int year = Y;
    int count = 0;
    while (count < N) {
        if (isLeap.test(year)) {
            count++;
            if (count == N) {
                return year;
            }
        }
        year++;
    }
    // In theory we will always return inside the loop
    return year;
}

public java.util.List<java.util.List<Integer>> permute(int[] nums) {
    java.util.List<java.util.List<Integer>> result = new java.util.ArrayList<>();
    for (int num : nums) {
        if (result.isEmpty()) {
            java.util.List<Integer> list = new java.util.ArrayList<>();
            list.add(num);
            result.add(list);
            continue;
        }
        java.util.List<java.util.List<Integer>> newResult = new java.util.ArrayList<>();
        for (java.util.List<Integer> perm : result) {
            for (int i = 0; i <= perm.size(); i++) {
                java.util.List<Integer> newPerm = new java.util.ArrayList<>(perm);
                newPerm.add(i, num);
                newResult.add(newPerm);
            }
        }
        result = newResult;
    }
    return result;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) {
        return 0;
    }
    int rows = grid.length;
    int cols = grid[0].length;
    boolean[][] visited = new boolean[rows][cols];
    int count = 0;
    int[] dRow = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dCol = {-1, 0, 1, -1, 1, -1, 0, 1};

    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                count++;
                // DFS/BFS to mark component
                java.util.Deque<int[]> stack = new java.util.ArrayDeque<>();
                stack.push(new int[]{r, c});
                visited[r][c] = true;
                while (!stack.isEmpty()) {
                    int[] cell = stack.pop();
                    int cr = cell[0], cc = cell[1];
                    for (int k = 0; k < 8; k++) {
                        int nr = cr + dRow[k];
                        int nc = cc + dCol[k];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols
                                && grid[nr][nc] == '@' && !visited[nr][nc]) {
                            visited[nr][nc] = true;
                            stack.push(new int[]{nr, nc});
                        }
                    }
                }
            }
        }
    }
    return count;
}

