public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Convert coordinate arrays to string keys
    java.util.function.Function<int[], String> keyFunc = coords -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (i > 0) sb.append(',');
            sb.append(coords[i]);
        }
        return sb.toString();
    };
    String startKey = keyFunc.apply(start);
    String endKey = keyFunc.apply(end);

    // If start and end are the same point
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }

    // Build adjacency map
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    for (int[] path : paths) {
        if (path.length != 2 * n) continue; // invalid path, skip
        int[] a = new int[n];
        int[] b = new int[n];
        System.arraycopy(path, 0, a, 0, n);
        System.arraycopy(path, n, b, 0, n);
        String aKey = keyFunc.apply(a);
        String bKey = keyFunc.apply(b);
        adj.computeIfAbsent(aKey, k -> new java.util.ArrayList<>()).add(bKey);
        adj.computeIfAbsent(bKey, k -> new java.util.ArrayList<>()).add(aKey);
    }

    // BFS to find path from start to end
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String cur = queue.poll();
        java.util.List<String> neighbors = adj.get(cur);
        if (neighbors == null) continue;
        for (String nb : neighbors) {
            if (nb.equals(endKey)) {
                return "can be travelled";
            }
            if (visited.add(nb)) {
                queue.add(nb);
            }
        }
    }

    return "cannot be travelled";
}

public static String convertDatesToWeekdays(String date) {
    String[] parts = date.split(" ");
    int month = Integer.parseInt(parts[0]);
    int day = Integer.parseInt(parts[1]);
    int year = Integer.parseInt(parts[2]);

    String[] monthNames = {"January","February","March","April","May","June","July",
                           "August","September","October","November","December"};
    String[] weekDays = {"Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"};

    java.util.Calendar cal = java.util.Calendar.getInstance();
    cal.set(year, month - 1, day, 0, 0, 0);
    cal.set(java.util.Calendar.MILLISECOND, 0);
    int dayOfWeekIndex = cal.get(java.util.Calendar.DAY_OF_WEEK); // 1 = Sunday, 7 = Saturday
    String weekday = weekDays[dayOfWeekIndex - 1];

    return monthNames[month - 1] + " " + day + ", " + year + " is a " + weekday;
}

