    for (int i = 0; i < n; i++) g[i] = new java.util.ArrayList<>();
    for (int[] e : edges) {
        g[e[0]].add(e[1]);
        g[e[1]].add(e[0]);
    }
    int[] res = new int[1];
    dfs(0, -1, g, hasApple, res);
    return res[0];
}

private boolean dfs(int node, int parent, java.util.List<Integer>[] g, boolean[] hasApple, int[] res) {
    boolean flag = hasApple[node];
    for (int child : g[node]) {
        if (child == parent) continue;
        boolean childFlag = dfs(child, node, g, hasApple, res);
        if (childFlag) {
            res[0] += 2;
            flag = true;
        }
    }
    return flag;
}

public String sortString(String s) {
    int[] count = new int[256];
    int total = s.length();
    for (int i = 0; i < total; i++) {
        count[s.charAt(i)]++;
    }

    StringBuilder result = new StringBuilder(total);

    while (total > 0) {
        // ascending pass
        for (int i = 0; i < 256 && total > 0; i++) {
            if (count[i] > 0) {
                result.append((char) i);
                count[i]--;
                total--;
                for (int j = i + 1; j < 256 && total > 0; j++) {
                    while (count[j] > 0) {
                        result.append((char) j);
                        count[j]--;
                        total--;
                    }
                }
                break;
            }
        }
        if (total == 0) break;

        // descending pass
        for (int i = 255; i >= 0 && total > 0; i--) {
            if (count[i] > 0) {
                result.append((char) i);
                count[i]--;
                total--;
                for (int j = i - 1; j >= 0 && total > 0; j--) {
                    while (count[j] > 0) {
                        result.append((char) j);
                        count[j]--;
                        total--;
                    }
                }
                break;
            }
        }
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    long totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }

    // sumsByCount[k] contains all possible sums of subsets with size k
    @SuppressWarnings("unchecked")
    java.util.HashSet<Integer>[] sumsByCount = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) {
        sumsByCount[i] = new java.util.HashSet<>();
    }
    sumsByCount[0].add(0);

    for (int num : nums) {
        for (int cnt = n - 1; cnt >= 0; cnt--) {
            for (int sum : sumsByCount[cnt]) {
                sumsByCount[cnt + 1].add(sum + num);
            }
        }
    }

    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) {
            continue;
        }
        int target = (int) ((totalSum * k) / n);
        if (sumsByCount[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int[] dp = new int[n + 3]; // dp[i] represents the min cost to reach the top from step i
    for (int i = n - 1; i >= 0; i--) {
        dp[i] = cost[i] + Math.min(dp[i + 1], dp[i + 2]);
    }
    return Math.min(dp[0], dp[1]); // can start from step 0 or step 1
}

