public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int maxEnding = nums[0];
    int maxSoFar = nums[0];
    int minEnding = nums[0];
    int minSoFar = nums[0];
    for (int i = 1; i < nums.length; i++) {
        int val = nums[i];
        maxEnding = Math.max(val, maxEnding + val);
        maxSoFar = Math.max(maxSoFar, maxEnding);
        minEnding = Math.min(val, minEnding + val);
        minSoFar = Math.min(minSoFar, minEnding);
    }
    int absMax = Math.abs(maxSoFar);
    int absMin = Math.abs(minSoFar);
    return Math.max(absMax, absMin);
}

public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci numbers up to k
    int maxSize = 50; // Enough for int range
    int[] fibs = new int[maxSize];
    int fibCount = 0;
    fibs[fibCount++] = 1;
    if (k > 1) {
        fibs[fibCount++] = 1;
    } else {
        // k == 1, only one Fibonacci number needed
        return 1;
    }
    while (true) {
        long next = (long) fibs[fibCount - 1] + fibs[fibCount - 2];
        if (next > k) {
            break;
        }
        fibs[fibCount++] = (int) next;
    }

    // Greedy: pick the largest Fibonacci numbers first
    int remaining = k;
    int count = 0;
    for (int i = fibCount - 1; i >= 0 && remaining > 0; i--) {
        if (fibs[i] <= remaining) {
            remaining -= fibs[i];
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    java.util.ArrayList<Integer> small = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> large = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            small.add(i);
            if (i * i != n) {
                large.add(n / i);
            }
        }
    }
    // Combine small factors in ascending order and large factors in descending order
    int totalFactors = small.size() + large.size();
    if (k > totalFactors) return -1;
    if (k <= small.size()) {
        return small.get(k - 1);
    } else {
        int idx = k - small.size() - 1; // 0-based index in descending order
        return large.get(large.size() - 1 - idx);
    }
}

public String makeGood(String s) {
