public static int singleNumber(int[] nums) {
    int result = 0;
    for (int i = 0; i < 32; i++) {
        int bitCnt = 0;
        for (int num : nums) {
            bitCnt += (num >> i) & 1;
        }
        if (bitCnt % 3 != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }
    if (high < 0) {
        return result;
    }
    // 0 is a stepping number if within bounds
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }

    Queue<Long> queue = new LinkedList<>();

    // Initialize queue with single digit numbers 1-9
    for (int d = 1; d <= 9; d++) {
        if (d > high) {
            break;
        }
        queue.offer((long) d);
        if (d >= low) {
            result.add(d);
        }
    }

    while (!queue.isEmpty()) {
        long current = queue.poll();
        int lastDigit = (int) (current % 10);

        // Append lastDigit - 1 if valid
        if (lastDigit > 0) {
            long next = current * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
                if (next >= low) {
                    result.add((int) next);
                }
            }
        }

        // Append lastDigit + 1 if valid
        if (lastDigit < 9) {
            long next = current * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
                if (next >= low) {
                    result.add((int) next);
                }
            }
        }
    }

    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }
    long count = 0;
    long factor = 1;
    while (factor <= n) {
        long lower = n % factor;
        long current = (n / factor) % 10;
        long higher = n / (factor * 10);

        if (current == 0) {
            count += higher * factor;
        } else if (current == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }

        factor *= 10;
    }
    return (int) count;
}

