        count++;
        if (count == 3 && val > 0) {
            sb.append('.');
            count = 0;
        }
    }
    if (negative) {
        sb.append('-');
    }
    return sb.reverse().toString();
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int[] left = new int[n];
    int[] right = new int[n];
    java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();

    // Compute left limits
    for (int i = 0; i < n; i++) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        left[i] = stack.isEmpty() ? -1 : stack.peek();
        stack.push(i);
    }

    stack.clear();

    // Compute right limits
    for (int i = n - 1; i >= 0; i--) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        right[i] = stack.isEmpty() ? n : stack.peek();
        stack.push(i);
    }

    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        int width = right[i] - left[i] - 1;
        int area = heights[i] * width;
        if (area > maxArea) {
            maxArea = area;
        }
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    int m = mat.length;
    if (m == 0) {
        return new int[0];
    }
    int n = mat[0].length;
    int[] result = new int[m * n];
    int index = 0;
    int totalDiagonals = m + n - 1;
    for (int d = 0; d < totalDiagonals; d++) {
        int rowStart = Math.max(0, d - (n - 1));
        int rowEnd = Math.min(m - 1, d);
        if (d % 2 == 0) {
            for (int r = rowEnd; r >= rowStart; r--) {
                int c = d - r;
                result[index++] = mat[r][c];
            }
        } else {
            for (int r = rowStart; r <= rowEnd; r++) {
                int c = d - r;
                result[index++] = mat[r][c];
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1;
    }
    int j = digits.length - 1;
    while (j > i && digits[j] <= digits[i]) {
        j--;
    }
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    int l = i + 1, r = digits.length - 1;
    while (l < r) {
        char t = digits[l];
        digits[l] = digits[r];
        digits[r] = t;
        l++;
        r--;
    }
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        return -1;
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    result.addAll(build(n, n));
    return result;
}

private static List<String> build(int len, int targetLen) {
    List<String> res = new ArrayList<>();
    if (len == 0) {
        res.add("");
        return res;
    }
    if (len == 1) {
        res.add("0");
        res.add("1");
        res.add("8");
        return res;
    }
    List<String> inner = build(len - 2, targetLen);
    String[][] pairs = {
        {"0", "0"}, {"1", "1"}, {"6", "9"}, {"8", "8"}, {"9", "6"}
    };
    for (String[] pair : pairs) {
        // Skip numbers with leading zero unless length==1
        if (pair[0].equals("0") && len == targetLen) {
            continue;
        }
        for (String sub : inner) {
            res.add(pair[0] + sub + pair[1]);
        }
    }
    return res;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    int x0 = points[0][0], y0 = points[0][1];
    int x1 = points[1][0], y1 = points[1][1];
    int x2 = points[2][0], y2 = points[2][1];

    // Using the shoelace formula to compute twice the signed area
    int area2 = (x1 - x0) * (y2 - y0) - (x2 - x0) * (y1 - y0);
    return area2 != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    int[] ugly = new int[n];
    ugly[0] = 1;
    int p2 = 0, p3 = 0, p5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        int next = Math.min(next2, Math.min(next3, next5));
        ugly[i] = next;
        if (next == next2) {
            p2++;
            next2 = ugly[p2] * 2;
        }
        if (next == next3) {
            p3++;
            next3 = ugly[p3] * 3;
        }
        if (next == next5) {
            p5++;
            next5 = ugly[p5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }
    int max = 1;
    int count = 1;
    char prev = s.charAt(0);
    for (int i = 1; i < s.length(); i++) {
        char current = s.charAt(i);
        if (current == prev) {
            count++;
        } else {
            if (count > max) {
                max = count;
            }
            prev = current;
            count = 1;
        }
    }
    if (count > max) {
        max = count;
    }
    return max;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) return result;
    int current = 1;
    for (int i = 1; i <= n; i++) {
        result.add(current);
        if (current * 10 <= n) {
            current *= 10;
        } else if (current % 10 != 9 && current + 1 <= n) {
            current++;
        } else {
            while (current / 10 > 0 && current % 10 == 9) {
                current /= 10;
            }
            current = current / 10 + 1;
        }
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    java.util.HashMap<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : nums) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    // Worst case: use 1^2 repeatedly
    for (int i = 0; i <= n; i++) {
        dp[i] = i;
    }
    for (int i = 1; i <= n; i++) {
        int j = 1;
        while (j * j <= i) {
            int square = j * j;
            if (dp[i - square] + 1 < dp[i]) {
                dp[i] = dp[i - square] + 1;
            }
            j++;
        }
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    String[] words = s.split(" ", -1); // split on spaces, keep empty tokens
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < words.length; i++) {
        result.append(new StringBuilder(words[i]).reverse());
        if (i < words.length - 1) {
            result.append(' ');
        }
    }
    return result.toString();
}
